298	    /**
299	     * Builds the derived identity key that consolidates all owner duplicate detection into a
300	     * single value: the SHA-256 hex digest (see {@link #sha256Hex(String)}) over the normalized
301	     * E.164 {@code telephone}, the lower-cased {@code email} (empty when none) and the Soundex
302	     * code of the {@code lastName} (see {@link #soundex(String)}), joined by {@code '|'}. Two
303	     * owners are duplicates exactly when their whole identity keys are equal, so a difference in
304	     * any of the three parts — for example two household mates (same last name, so same Soundex)
305	     * with different telephones — yields distinct keys. A {@code null} telephone or email
306	     * contributes the empty string. The result is a 64-character lower-case hex string.
307	     *
308	     * @param telephone the normalized E.164 telephone
309	     * @param email the lower-cased email, or {@code null} when none
310	     * @param lastName the owner's last name, reduced to its Soundex code
311	     * @return the derived identity key, a 64-character lower-case hex SHA-256 digest
312	     */
313	    public static String identityKey(String telephone, String email, String lastName) {
314	        String key = (telephone == null ? "" : telephone) + "|"
315	            + (email == null ? "" : email.toLowerCase(Locale.ROOT)) + "|"
316	            + soundex(lastName);
317	        return sha256Hex(key);
318	    }
319	
320	    /**
321	     * Returns this owner's derived identity key, see
322	     * {@link #identityKey(String, String, String)}.
323	     *
324	     * @return the derived identity key for this owner
325	     */
326	    @Transient
327	    public String getIdentityKey() {
328	        return identityKey(this.telephone, this.email, this.lastName);
329	    }
330	
331	    /**
332	     * Returns this owner's identity hash: the leading 8 upper-case hex characters (see
333	     * {@link #shaHexPrefix(String, int)}) of the SHA-256 digest over the owner's normalized E.164
334	     * {@code telephone} concatenated with its {@code lastName}. This is the single definition of the
335	     * {@code HASH8} segment the region-and-hash identity is built from (see {@link #getRegionCode()}),
336	     * shared by every derived code that carries it.
337	     *
338	     * @return the owner's 8-character upper-case hex identity hash
339	     */
340	    @Transient
341	    public String getIdentityHash() {
342	        return shaHexPrefix(this.telephone + this.lastName, 8);
343	    }
344	
345	    /**
346	     * Computes the American Soundex code of a name: the retained first letter followed by up to
347	     * three digits encoding the remaining consonants ({@code B,F,P,V => 1}; {@code C,G,J,K,Q,S,X,Z
348	     * => 2}; {@code D,T => 3}; {@code L => 4}; {@code M,N => 5}; {@code R => 6}), with vowels and
349	     * {@code Y} acting as separators, {@code H} and {@code W} transparent (they do not break a run
350	     * of same-coded consonants), adjacent same-coded letters collapsed to a single digit, and the
351	     * code zero-padded to length 4. Non-letters are ignored. A {@code null} or letter-free name
352	     * yields the empty string. This is the single definition of the Soundex reduction shared by the
353	     * identity key ({@link #identityKey(String, String, String)}).
354	     *
355	     * @param name the name to encode, or {@code null}
356	     * @return the 4-character Soundex code, or the empty string when {@code name} has no letters
357	     */
358	    public static String soundex(String name) {
359	        if (name == null) {
360	            return "";
361	        }
362	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
363	        if (letters.isEmpty()) {
364	            return "";
365	        }
366	        StringBuilder code = new StringBuilder();
367	        code.append(letters.charAt(0));
368	        char previousCode = soundexCode(letters.charAt(0));
369	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
370	            char c = letters.charAt(i);
371	            if (c == 'H' || c == 'W') {
372	                continue;
373	            }
374	            char digit = soundexCode(c);
375	            if (digit != '0' && digit != previousCode) {
376	                code.append(digit);
377	            }
378	            previousCode = digit;
379	        }
380	        while (code.length() < 4) {
381	            code.append('0');
382	        }
383	        return code.toString();
384	    }
385	
386	    /**
387	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for a vowel, {@code Y},
388	     * {@code H} or {@code W} (the letters that do not contribute a digit). See
389	     * {@link #soundex(String)} for the digit groups.
390	     *
391	     * @param c the upper-case letter to encode
392	     * @return the Soundex digit {@code '1'}-{@code '6'}, or {@code '0'} when the letter contributes none
393	     */
394	    private static char soundexCode(char c) {
395	        switch (c) {
396	            case 'B': case 'F': case 'P': case 'V':
397	                return '1';
398	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
399	                return '2';
400	            case 'D': case 'T':
401	                return '3';
402	            case 'L':
403	                return '4';
404	            case 'M': case 'N':
405	                return '5';
406	            case 'R':
407	                return '6';
408	            default:
409	                return '0';
410	        }
411	    }
412	
413	    /**
414	     * Computes the full lower-case hex SHA-256 digest of a string: the input is hashed as UTF-8
415	     * bytes and each of the 32 digest bytes is rendered as two lower-case hex digits, yielding a
416	     * 64-character string. This is the single definition of the SHA-256 hex derivation shared by
417	     * every rule that hashes owner fields (for example the customer code and household identifier,
418	     * each formed from the leading upper-case characters of this digest). SHA-256 is a required
419	     * platform algorithm; were it ever unavailable an {@link IllegalStateException} is thrown.
420	     *
421	     * @param input the string to hash
422	     * @return the 64-character lower-case hex SHA-256 digest of {@code input}
423	     */
424	    public static String sha256Hex(String input) {
425	        try {
426	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
427	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
428	            StringBuilder sb = new StringBuilder(digest.length * 2);
429	            for (byte b : digest) {
430	                sb.append(String.format("%02x", b));
431	            }
432	            return sb.toString();
433	        }
434	        catch (java.security.NoSuchAlgorithmException e) {
435	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
436	        }
437	    }
438	
439	    /**
440	     * Returns the leading {@code hexChars} upper-case hex characters of the SHA-256 digest of a
441	     * string (see {@link #sha256Hex(String)}). This is the single definition of the truncated
442	     * upper-case hex form the derived owner codes are built from — the region-and-hash identity's
443	     * {@code HASH8} (see {@link #getIdentityHash()}) and the household identifier each take a leading
444	     * slice of a digest — so {@code hexChars} characters cover the leading {@code ceil(hexChars / 2)}
445	     * bytes of the digest.
446	     *
447	     * @param input the string to hash
448	     * @param hexChars the number of leading upper-case hex characters to return
449	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest of {@code input}
450	     */
451	    public static String shaHexPrefix(String input, int hexChars) {
452	        return sha256Hex(input).substring(0, hexChars).toUpperCase(Locale.ROOT);
453	    }
454	
455	    /**
456	     * Fixed telephone country-code table: the exact national-number length (the count of digits
457	     * following the country code) each country code this application recognizes admits
458	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
459	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
460	     */
461	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
462	
463	    /**
464	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
465	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
466	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
467	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
468	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
469	     * no recognized country code. This is the single definition of how an E.164 telephone splits
470	     * from its country code, shared by every rule that reasons about a telephone's country code.
471	     *
472	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
473	     * @return the recognized country-code digits, or {@code null} when none is recognized
474	     */
475	    public static String countryCodeOf(String telephone) {
476	        if (telephone == null || !telephone.startsWith("+")) {
477	            return null;
478	        }
479	        String digits = telephone.substring(1);
480	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
481	            .filter(digits::startsWith)
482	            .max(Comparator.comparingInt(String::length))
483	            .orElse(null);
484	    }
485	
486	    /**
487	     * Resolves the exact national-number length (the count of digits following the country code) a
488	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
489	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
490	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
491	     * per-country length rule). This is the single definition of the per-country national-number
492	     * lengths, shared by every rule that relates a telephone's national number to its country code.
493	     *
494	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
495	     * @return the required national-number length, or {@code null} when the code is not recognized
496	     */
497	    public static Integer nationalNumberLength(String countryCode) {
498	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
499	    }
500	
501	    /**
502	     * Fixed city-to-region table: the canonical region each known city belongs to
503	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
504	     * absent from this table has no known region.
505	     */
506	    private static final Map<String, String> CITY_REGIONS = Map.of(
507	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
508	
509	    /**
510	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
511	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
512	     * region string, or {@code null} when the city has no known region. This is the single
513	     * definition of the city-to-region mapping, shared by every rule that derives a region
514	     * from an owner's city.
515	     *
516	     * @param city the city to resolve
517	     * @return the canonical region, or {@code null} when the city has no known region
518	     */
519	    public static String regionForCity(String city) {
520	        return CITY_REGIONS.get(city);
521	    }
522	
523	    /**
524	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
525	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
526	     * A region absent from this table has no fixed range.
527	     */
528	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
529	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
530	
531	    /**
532	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
533	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
534	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
535	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
536	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
537	     *
538	     * @param region the region to resolve, or {@code null}
539	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
540	     */
541	    public static int[] postcodeRangeForRegion(String region) {
542	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
543	    }
544	
545	    /**
546	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
547	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
548	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
549	     * value, or falls in no known range. This is the single definition of the postcode-to-region
550	     * mapping, shared by every rule that derives a region from a postcode.
551	     *
552	     * @param postcode the postcode to resolve
553	     * @return the canonical region, or {@code null} when the postcode maps to no known region
554	     */
555	    public static String regionForPostcode(String postcode) {
556	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
557	            return null;
558	        }
559	        int value = Integer.parseInt(postcode);
560	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
561	            int[] range = entry.getValue();
562	            if (value >= range[0] && value <= range[1]) {
563	                return entry.getKey();
564	            }
565	        }
566	        return null;
567	    }
568	
569	    /**
570	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
571	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
572	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
573	     * range does derivation fall back to the fixed city-to-region table (see
574	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
575	     * resolves to a known region. This is the single definition of an owner's region, shared by
576	     * every rule that derives a region from an owner.
577	     *
578	     * @return the owner's canonical region, or {@code null} when it has no known region
579	     */
580	    @Transient
581	    public String getRegion() {
582	        String region = regionForPostcode(this.postcode);
583	        return region != null ? region : regionForCity(this.city);
584	    }
585	
586	    /**
587	     * Returns the region code carried by this owner's derived identity: the owner's canonical region
588	     * (see {@link #getRegion()}), or the sentinel {@code 'UNKNOWN'} when the owner has no known
589	     * region. Unlike {@link #getRegion()} this never returns {@code null}, so it is the single
590	     * definition of the {@code REGION} segment the region-and-hash identity leads with (see
591	     * {@link #getIdentityHash()}).
592	     *
593	     * @return the owner's region code, or {@code 'UNKNOWN'} when it has no known region
594	     */
595	    @Transient
596	    public String getRegionCode() {
597	        String region = getRegion();
598	        return region != null ? region : "UNKNOWN";
599	    }
600	
601	    /**
602	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
603	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
604	     * owner "having an email", shared by every rule that turns email presence into a derived value
605	     * (its membership factor and its {@code contactPreference}).
606	     *
607	     * @param email the owner's email, or {@code null}
608	     * @return {@code true} when the email is present and not blank
609	     */
610	    public static boolean hasEmail(String email) {
611	        return email != null && !email.isBlank();
612	    }
613	
614	    /**
615	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
616	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
617	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
618	     * every rule that rewards an owner for being unique by name.
619	     *
620	     * @param namesakeCount the owner's namesake count, or {@code null}
621	     * @return {@code true} when the owner is known to have no namesakes
622	     */
623	    public static boolean hasNoNamesakes(Integer namesakeCount) {
624	        return namesakeCount != null && namesakeCount == 0;
625	    }
626	
627	    /**
628	     * Resolves the fiscal year a date falls in. The fiscal year starts on 1 July, so a date in July
629	     * through December belongs to the fiscal year of the following calendar year, while a date in
630	     * January through June belongs to the fiscal year of its own calendar year (for example both
631	     * 2025-08-01 and 2026-03-01 fall in fiscal year 2026). This is the single definition of the
632	     * date-to-fiscal-year mapping, shared by every value derived on a fiscal-year basis (the
633	     * {@code fiscalYear}, the membership number's year segment and tenure).
634	     *
635	     * @param date the date to resolve, never {@code null}
636	     * @return the fiscal year the date falls in
637	     */
638	    public static int fiscalYearOf(LocalDate date) {
639	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
640	    }
641	
642	    /**
643	     * Renders the two-digit fiscal-year segment ({@code YY}) of a date: the last two digits of the
644	     * fiscal year the date falls in (see {@link #fiscalYearOf(LocalDate)}), zero-padded to two
645	     * characters (for example both 2025-08-01 and 2026-03-01 render {@code '26'}). This is the single
646	     * definition of the {@code YY} fiscal-year segment, shared by every value that carries it (the
647	     * {@code fiscalYear} and the membership number's year segment).
648	     *
649	     * @param date the date to resolve, never {@code null}
650	     * @return the two-digit fiscal-year segment the date falls in
651	     */
652	    public static String fiscalYearSegment(LocalDate date) {
653	        return String.format("%02d", fiscalYearOf(date) % 100);
654	    }
655	
656	    /**
657	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
658	     * {@code asOf}: the number of elapsed fiscal years between the two dates (see
659	     * {@link #fiscalYearOf(LocalDate)}) exceeds {@code 1}. Returns {@code false} when
660	     * {@code registrationDate} is absent, so the owner has no derivable tenure; because a newly
661	     * created owner has zero elapsed fiscal years, it never counts as long-tenured. This is the
662	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
663	     * an owner for tenure beyond a fiscal year.
664	     *
665	     * @param registrationDate the owner's registration date, or {@code null}
666	     * @param asOf the date the tenure is measured against
667	     * @return {@code true} when the owner's tenure exceeds one elapsed fiscal year
668	     */
669	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
670	        return registrationDate != null && fiscalYearOf(asOf) - fiscalYearOf(registrationDate) > 1;
671	    }
672	
673	    /**
674	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
675	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
676	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
677	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
678	     *
679	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
680	     * @return {@code true} when the owner is known to belong to a household of three or more
681	     */
682	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
683	        return householdMemberCount != null && householdMemberCount >= 3;
684	    }
685	
686	    /**
687	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
688	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
689	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
690	     * {@code 3} when the owner's tenure exceeds one elapsed fiscal year. Because a newly created
691	     * owner has zero tenure, the tenure points are never awarded on creation. This is the single source the
692	     * membership level is derived from (see {@link #getMembershipLevel()}).
693	     *
694	     * @return the owner's membership points
695	     */
696	    @Transient
697	    public Integer getMembershipPoints() {
698	        LocalDate today = LocalDate.now();
699	        int points = 0;
700	        if (hasEmail(this.email)) {
701	            points += 2;
702	        }
703	        if (hasNoNamesakes(this.namesakeCount)) {
704	            points += 1;
705	        }
706	        if (hasLargeHousehold(this.householdMemberCount)) {
707	            points += 2;
708	        }
709	        if (hasLongTenure(this.registrationDate, today)) {
710	            points += 3;
711	        }
712	        return points;
713	    }
714	
715	    /**
716	     * Resolves the numeric membership level a given number of membership points earns: {@code 1} for
717	     * {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for
718	     * {@code 6} or more points. This is the single definition of the points-to-level mapping, shared
719	     * by every rule that derives a membership level from points (see {@link #getMembershipLevel()}).
720	     *
721	     * @param points the membership points to map
722	     * @return the membership level those points earn
723	     */
724	    public static int membershipLevelForPoints(int points) {
725	        if (points >= 6) {
726	            return 4;
727	        }
728	        if (points >= 4) {
729	            return 3;
730	        }
731	        if (points >= 2) {
732	            return 2;
733	        }
734	        return 1;
735	    }
736	
737	    /**
738	     * Applies an owner's household level ceiling to a membership level: the level is returned
739	     * unchanged when {@code cap} is {@code null} (no ceiling applies), otherwise it is capped at
740	     * {@code cap} so it can never exceed it. This is the single definition of how the household
741	     * level ceiling caps a membership level, shared by every rule that reads a capped membership
742	     * level (see {@link #getMembershipLevel()}).
743	     *
744	     * @param level the uncapped membership level derived from the owner's points
745	     * @param cap the owner's household level ceiling, or {@code null} when no ceiling applies
746	     * @return the membership level after applying the ceiling
747	     */
748	    public static int cappedMembershipLevel(int level, Integer cap) {
749	        return cap == null ? level : Math.min(level, cap);
750	    }
751	
752	    /**
753	     * Returns this owner's numeric membership level, derived from its membership points (see
754	     * {@link #getMembershipPoints()}) by the single points-to-level mapping (see
755	     * {@link #membershipLevelForPoints(int)}): {@code 1} for {@code 0-1} points, {@code 2} for
756	     * {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points. The
757	     * result is then held to the owner's household level ceiling {@code membershipLevelCap} (see
758	     * {@link #cappedMembershipLevel(int, Integer)}): a new owner joining a household may earn a
759	     * level at most one above the highest level among its existing household members, and no
760	     * ceiling applies when the owner joined an empty household.
761	     *
762	     * @return the owner's membership level, capped by its household level ceiling
763	     */
764	    @Transient
765	    public Integer getMembershipLevel() {
766	        return cappedMembershipLevel(membershipLevelForPoints(getMembershipPoints()), this.membershipLevelCap);
767	    }
768	
769	    /**
770	     * Returns this owner's fiscal year formatted as {@code 'FY<YY>'}, where YY is the two-digit
771	     * fiscal-year segment carried by the owner's {@code memberId} (see {@link #getMemberId()}), the
772	     * segment immediately following the leading region code. Because the {@code memberId} is the
773	     * unified identity the fiscal year is now read from, this returns {@code null} when the owner has
774	     * no {@code memberId}, so the fiscal year cannot be derived. The two-digit segment is the last two
775	     * digits of the fiscal year (starting 1 July, see {@link #fiscalYearOf(LocalDate)}) the owner's
776	     * business-day-adjusted {@code registrationDate} fell in when the {@code memberId} was assigned,
777	     * e.g. a {@code memberId} of {@code 'NSW26A1B2C3D45'} yields {@code 'FY26'}. This is the single
778	     * definition of an owner's fiscal year.
779	     *
780	     * @return the owner's fiscal year, or {@code null} when it cannot be derived
781	     */
782	    @Transient
783	    public String getFiscalYear() {
784	        if (this.memberId == null) {
785	            return null;
786	        }
787	        String core = this.memberId;
788	        int dash = core.indexOf('-');
789	        if (dash >= 0) {
790	            core = core.substring(0, dash);
791	        }
792	        return "FY" + core.substring(core.length() - 11, core.length() - 9);
793	    }
794	
795	    /**
796	     * Computes the single Luhn check digit (0-9) over the digits contained in a string: reading from
797	     * the right, every second digit is doubled (subtracting 9 when the result exceeds 9), the digits
798	     * are summed and the check digit is the amount that rounds the sum up to the next multiple of ten.
799	     * Non-digit characters are skipped, so a code mixing letters and digits contributes only its
800	     * digits. This is the single definition of the Luhn check digit, shared by every value that
801	     * carries one (the {@code CHK} segment of the unified member id, see {@link #getMemberId()}).
802	     *
803	     * @param code the string whose digits the check digit is computed over
804	     * @return the Luhn check digit (0-9) of {@code code}
805	     */
806	    public static int luhnCheckDigit(String code) {
807	        int sum = 0;
808	        boolean dbl = true;
809	        for (int i = code.length() - 1; i >= 0; i--) {
810	            char c = code.charAt(i);
811	            if (c < '0' || c > '9') {
812	                continue;
813	            }
814	            int d = c - '0';
815	            if (dbl) {
816	                d *= 2;
817	                if (d > 9) {
818	                    d -= 9;
819	                }
820	            }
821	            sum += d;
822	            dbl = !dbl;
823	        }
824	        return (10 - (sum % 10)) % 10;
825	    }
826	
827	    /**
828	     * Returns this owner's age band, derived from {@code birthDate} computed against
829	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
830	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
831	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
832	     * band cannot be derived. This is the single definition of an owner's age band.
833	     *
834	     * @return the owner's age band, or {@code null} when it cannot be derived
835	     */
836	    @Transient
837	    public String getAgeBand() {
838	        if (this.birthDate == null || this.registrationDate == null) {
839	            return null;
840	        }
841	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
842	        if (age < 18) {
843	            return "MINOR";
844	        }
845	        if (age < 65) {
846	            return "ADULT";
847	        }
848	        return "SENIOR";
849	    }
850	
851	    protected Set<Pet> getPetsInternal() {
852	        if (this.pets == null) {
853	            this.pets = new HashSet<>();
854	        }
855	        return this.pets;
856	    }
857	
858	    protected void setPetsInternal(Set<Pet> pets) {
859	        this.pets = pets;
860	    }
861	
862	    public List<Pet> getPets() {
863	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
864	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
865	        return Collections.unmodifiableList(sortedPets);
866	    }
867	
868	    public void setPets(List<Pet> pets) {
869	        this.pets = new HashSet<>(pets);
870	    }
871	
872	    public void addPet(Pet pet) {
873	        getPetsInternal().add(pet);
874	        pet.setOwner(this);
875	    }
876	
877	    /**
878	     * Return the Pet with the given name, or null if none found for this Owner.
879	     *
880	     * @param name to test
881	     * @return true if pet name is already in use
882	     */
883	    public Pet getPet(String name) {
884	        return getPet(name, false);
885	    }
886	
887	    /**
888	     * Return the Pet with the given name, or null if none found for this Owner.
889	     *
890	     * @param name to test
891	     * @return true if pet name is already in use
892	     */
893	    public Pet getPet(String name, boolean ignoreNew) {
894	        name = name.toLowerCase();
895	        for (Pet pet : getPetsInternal()) {
896	            if (!ignoreNew || !pet.isNew()) {
897	                String compName = pet.getName();
898	                compName = compName.toLowerCase();
899	                if (compName.equals(name)) {
900	                    return pet;
901	                }
902	            }
903	        }
904	        return null;
905	    }
906	
907	    public Pet getPet(Integer petId) {
908	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
909	    }
910	
911	    @Override
912	    public String toString() {
913	        return new ToStringCreator(this)
914	
915	            .append("id", this.getId())
916	            .append("new", this.isNew())
917	            .append("lastName", this.getLastName())
918	            .append("firstName", this.getFirstName())
919	            .append("address", this.address)
920	            .append("city", this.city)
921	            .append("telephone", this.telephone)
922	            .append("email", this.email)
923	            .toString();
924	    }
925	}
