65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
75	
76	    private final ClinicService clinicService;
77	
78	    private final OwnerMapper ownerMapper;
79	
80	    private final PetMapper petMapper;
81	
82	    private final VisitMapper visitMapper;
83	
84	    private final HttpServletRequest request;
85	
86	    /**
87	     * HTTP header carrying the client-supplied idempotency key for the create endpoint. When a
88	     * create repeats with a key already seen, the originally created owner is returned instead of
89	     * creating a duplicate.
90	     */
91	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
92	
93	    /**
94	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that key's create produced,
95	     * so a repeat create with the same key can return the originally created owner rather than
96	     * persisting a duplicate. Shared across requests, hence concurrency-safe.
97	     */
98	    private static final Map<String, Integer> IDEMPOTENT_CREATES = new ConcurrentHashMap<>();
99	
100	    /**
101	     * Source of the {@code seq} carried by each structured {@code OWNER_CREATED} audit event: a
102	     * monotonically increasing integer stamped once per successful create, in creation order.
103	     * Shared across requests, hence concurrency-safe.
104	     */
105	    private static final AtomicLong OWNER_CREATED_SEQ = new AtomicLong(0);
106	
107	    public OwnerRestControllerV1(ClinicService clinicService,
108	                                 OwnerMapper ownerMapper,
109	                                 PetMapper petMapper,
110	                                 VisitMapper visitMapper,
111	                                 HttpServletRequest request) {
112	        this.clinicService = clinicService;
113	        this.ownerMapper = ownerMapper;
114	        this.petMapper = petMapper;
115	        this.visitMapper = visitMapper;
116	        this.request = request;
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
122	        Collection<Owner> owners;
123	        if (lastName != null) {
124	            owners = this.clinicService.findOwnerByLastName(lastName);
125	        } else {
126	            owners = this.clinicService.findAllOwners();
127	        }
128	        if (owners.isEmpty()) {
129	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
130	        }
131	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
137	        Owner owner = this.clinicService.findOwnerById(ownerId);
138	        if (owner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        return okOwnerResponse(owner);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
147	        String idempotencyKey = idempotencyKey();
148	        if (idempotencyKey != null) {
149	            ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
150	            if (replay != null) {
151	                return replay;
152	            }
153	        }
154	        Owner owner = createOwner(ownerFieldsDto);
155	        if (idempotencyKey != null) {
156	            IDEMPOTENT_CREATES.put(idempotencyKey, owner.getId());
157	        }
158	        return createdOwnerResponse(owner);
159	    }
160	
161	    /**
162	     * Reads the request's {@code Idempotency-Key} header, returning the trimmed key or {@code null}
163	     * when the header is absent or blank. A blank key carries no intent to deduplicate, so the
164	     * create proceeds normally.
165	     *
166	     * @return the non-blank idempotency key, or {@code null} when none was supplied
167	     */
168	    private String idempotencyKey() {
169	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
170	        if (key == null || key.isBlank()) {
171	            return null;
172	        }
173	        return key.trim();
174	    }
175	
176	    /**
177	     * Replays the create originally produced by the given {@code Idempotency-Key}, if any: when the
178	     * key has already created an owner that still exists, that owner is rendered with {@code 200 OK}
179	     * (rather than creating a duplicate with {@code 201 Created}). When the key has not been seen, or
180	     * the owner it created no longer exists, {@code null} is returned so the caller creates the owner
181	     * normally.
182	     *
183	     * @param idempotencyKey the non-blank idempotency key supplied on the request
184	     * @return the {@code 200 OK} response carrying the originally created owner, or {@code null}
185	     */
186	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
187	        Integer existingId = IDEMPOTENT_CREATES.get(idempotencyKey);
188	        if (existingId == null) {
189	            return null;
190	        }
191	        Owner existing = this.clinicService.findOwnerById(existingId);
192	        if (existing == null) {
193	            return null;
194	        }
195	        return okOwnerResponse(existing);
196	    }
197	
198	    /**
199	     * Runs the full intake pipeline for a newly submitted owner and persists the result, returning
200	     * the saved {@link Owner}. The submitted fields are normalized and validated
201	     * ({@link #prepareNewOwner(OwnerFieldsDto, LocalDate)}) against the effective business-day
202	     * {@code registrationDate} ({@link #effectiveRegistrationDate(OwnerFieldsDto)}); the owner is
203	     * then mapped, stamped with that registration date and every derived value (member id,
204	     * namesake count, household), flagged as a possible duplicate where applicable, saved, and
205	     * finally stamped with its household member count. A rule that rejects the owner signals it by
206	     * throwing, which the exception advice renders as the matching 4xx response, so this method
207	     * returns only for an owner that was accepted and persisted. The create is audited once the
208	     * owner has its identity.
209	     *
210	     * <p>The returned owner carries its generated id and every stored field, ready to be rendered by
211	     * {@link #createdOwnerResponse(Owner)}.
212	     *
213	     * @param ownerFieldsDto the submitted owner fields, normalized in place
214	     * @return the persisted owner
215	     */
216	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
217	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
218	        prepareNewOwner(ownerFieldsDto, registrationDate);
219	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
220	        owner.setRegistrationDate(registrationDate);
221	        owner.setMemberId(memberIdFor(owner));
222	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
223	        assignHousehold(owner);
224	        applyPossibleDuplicate(owner, ownerFieldsDto);
225	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
226	        this.clinicService.saveOwner(owner);
227	        applyHouseholdMemberCount(owner);
228	        auditOwnerCreated(owner);
229	        emitOwnerCreatedEvent(owner);
230	        enqueueWelcomeNotification(owner);
231	        return owner;
232	    }
233	
234	    /**
235	     * Enqueues a welcome notification for a freshly persisted owner by emitting a line to the
236	     * dedicated {@code NOTIFY} logger carrying the owner's {@code id} and its unified
237	     * {@code memberId}. This runs only on a successful create — once the owner has its generated
238	     * identity and derived member id — so downstream consumers watching the {@code NOTIFY} logger
239	     * can react to new members structurally.
240	     *
241	     * @param owner the persisted owner, already carrying its generated id and derived member id
242	     */
243	    private void enqueueWelcomeNotification(Owner owner) {
244	        NOTIFY.info("Welcome notification queued: id={} memberId={}",
245	            owner.getId(), owner.getMemberId());
246	    }
247	
248	    /**
249	     * Writes the human-readable {@code Owner created} audit line for a freshly persisted owner,
250	     * carrying its {@code id}, its unified {@code memberId}, its stored {@code registrationDate} and
251	     * its derived {@code membershipLevel}. This is the free-form companion to the structured
252	     * {@code OWNER_CREATED} event (see {@link #emitOwnerCreatedEvent(Owner)}); isolating it here
253	     * keeps {@link #createOwner(OwnerFieldsDto)} a thin orchestration and gives the audit line one
254	     * place to grow.
255	     *
256	     * @param owner the persisted owner, already carrying its generated id and derived values
257	     */
258	    private void auditOwnerCreated(Owner owner) {
259	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
260	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
261	            owner.getMembershipLevel());
262	    }
263	
264	    /**
265	     * Emits the immutable, structured {@code OWNER_CREATED} audit event for a freshly persisted owner,
266	     * alongside the human-readable audit line. The event is a JSON object carrying, in order, a
267	     * {@code seq} (a monotonically increasing integer across creates, see {@link #OWNER_CREATED_SEQ}),
268	     * the owner's {@code ownerId}, the owner's current primary identifier (see
269	     * {@link #primaryIdentifier(Owner)}) under the {@code memberId} key, the owner's derived
270	     * {@code membershipLevel}, and the {@code event} marker {@code 'OWNER_CREATED'}. Published to the
271	     * dedicated {@code AUDIT} logger so downstream consumers can react to owner creation structurally
272	     * rather than by parsing the free-form line.
273	     *
274	     * @param owner the persisted owner, already carrying its generated id and derived values
275	     */
276	    private void emitOwnerCreatedEvent(Owner owner) {
277	        long seq = OWNER_CREATED_SEQ.incrementAndGet();
278	        AUDIT.info("{\"seq\":{},\"ownerId\":{},\"memberId\":{},\"membershipLevel\":{},\"event\":\"OWNER_CREATED\"}",
279	            seq, owner.getId(), jsonString(primaryIdentifier(owner)), owner.getMembershipLevel());
280	    }
281	
282	    /**
283	     * Returns the owner's current primary identifier, the single identity the structured
284	     * {@code OWNER_CREATED} event carries: the owner's unified {@code memberId}. This is the one seam
285	     * that decides which field is primary, so the event carries the member id under its
286	     * {@code memberId} key.
287	     *
288	     * @param owner the persisted owner whose primary identifier the event should carry
289	     * @return the owner's current primary identifier
290	     */
291	    private String primaryIdentifier(Owner owner) {
292	        return owner.getMemberId();
293	    }
294	
295	    /**
296	     * Renders a value as a JSON string literal for the structured audit event: {@code null} becomes
297	     * the JSON {@code null} keyword, otherwise the value is quoted with the JSON-significant
298	     * characters ({@code "} and {@code \}) escaped. The derived identifiers this carries never contain
299	     * such characters, but escaping keeps the emitted event valid JSON regardless.
300	     *
301	     * @param value the value to render, or {@code null}
302	     * @return the JSON representation of the value
303	     */
304	    private String jsonString(String value) {
305	        if (value == null) {
306	            return "null";
307	        }
308	        return "\"" + value.replace("\\", "\\\\").replace("\"", "\\\"") + "\"";
309	    }
310	
311	    /**
312	     * Renders a persisted owner as the {@code 201 Created} response of the create endpoint. The owner
313	     * is mapped to an {@link OwnerDto}, its {@code bulkSignupWarning} is derived from the owner's
314	     * stored {@code registrationDate} (mirroring {@link #getOwner(Integer)}), and a {@code Location}
315	     * header pointing at {@code /api/owners/{id}} is attached. Isolating the response assembly here
316	     * keeps {@link #addOwner(OwnerFieldsDto)} a thin orchestration of "create the owner, then render
317	     * it" and gives the created representation one place to grow.
318	     *
319	     * @param owner the persisted owner to render, carrying its generated id and stored fields
320	     * @return the {@code 201 Created} response carrying the owner representation and {@code Location} header
321	     */
322	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner) {
323	        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
324	        HttpHeaders headers = new HttpHeaders();
325	        headers.setLocation(UriComponentsBuilder.newInstance()
326	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
327	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
328	    }
329	
330	    /**
331	     * Renders a persisted owner as the {@code 200 OK} response shared by the read path
332	     * ({@link #getOwner(Integer)}) and the idempotent-replay path
333	     * ({@link #replayIdempotentCreate(String)}): the owner is stamped with its household member
334	     * count and then mapped to an {@link OwnerDto} carrying its {@code bulkSignupWarning} (see
335	     * {@link #toOwnerDtoWithWarning(Owner)}). Isolating the assembly here keeps both paths rendering
336	     * an existing owner identically rather than each copying the same steps.
337	     *
338	     * @param owner the persisted owner to render
339	     * @return the {@code 200 OK} response carrying the owner representation
340	     */
341	    private ResponseEntity<OwnerDto> okOwnerResponse(Owner owner) {
342	        applyHouseholdMemberCount(owner);
343	        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
344	    }
345	
346	    /**
347	     * Maps a persisted owner to the {@link OwnerDto} returned by every rendered response, stamping
348	     * its {@code bulkSignupWarning} from the owner's stored {@code registrationDate} (see
349	     * {@link #bulkSignupWarning(LocalDate)}) and its {@code capacityWarning} from the owner's
350	     * {@code city} (see {@link #capacityWarning(String)}). This is the single definition of how an
351	     * owner becomes its response representation, shared by the read, idempotent-replay and create
352	     * responses, so all three derive the rendered fields identically rather than each copying the
353	     * mapping.
354	     *
355	     * @param owner the persisted owner to map
356	     * @return the owner representation with its {@code bulkSignupWarning} and {@code capacityWarning} set
357	     */
358	    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
359	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
360	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
361	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
362	        return ownerDto;
363	    }
364	
365	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
366	    @Override
367	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
368	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
369	        if (currentOwner == null) {
370	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
371	        }
372	        currentOwner.setAddress(ownerFieldsDto.getAddress());
373	        currentOwner.setCity(ownerFieldsDto.getCity());
374	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
375	        currentOwner.setLastName(ownerFieldsDto.getLastName());
376	        currentOwner.setTitle(ownerFieldsDto.getTitle());
377	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
378	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
379	        this.clinicService.saveOwner(currentOwner);
380	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
381	    }
382	
383	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
384	    @Transactional
385	    @Override
386	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
387	        Owner owner = this.clinicService.findOwnerById(ownerId);
388	        if (owner == null) {
389	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
390	        }
391	        owner.setDeleted(true);
392	        this.clinicService.saveOwner(owner);
393	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
394	    }
395	
396	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
397	    @Override
398	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
399	        Owner owner = this.clinicService.findOwnerById(ownerId);
400	        if (owner == null) {
401	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
402	        }
403	        HttpHeaders headers = new HttpHeaders();
404	        Pet pet = petMapper.toPet(petFieldsDto);
405	        owner.setId(ownerId);
406	        pet.setOwner(owner);
407	        pet.getType().setName(null);
408	        this.clinicService.savePet(pet);
409	        PetDto petDto = petMapper.toPetDto(pet);
410	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
411	            .buildAndExpand(pet.getId()).toUri());
412	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
413	    }
414	
415	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
416	    @Override
417	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
418	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
419	        if (currentOwner != null) {
420	            Pet currentPet = this.clinicService.findPetById(petId);
421	            if (currentPet != null) {
422	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
423	                currentPet.setName(petFieldsDto.getName());
424	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
425	                this.clinicService.savePet(currentPet);
426	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
427	            }
428	        }
429	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
430	    }
431	
432	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
433	    @Override
434	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
435	        HttpHeaders headers = new HttpHeaders();
436	        Visit visit = visitMapper.toVisit(visitFieldsDto);
437	        Pet pet = new Pet();
438	        pet.setId(petId);
439	        visit.setPet(pet);
440	        this.clinicService.saveVisit(visit);
441	        VisitDto visitDto = visitMapper.toVisitDto(visit);
442	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
443	            .buildAndExpand(visit.getId()).toUri());
444	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
445	    }
446	
447	
448	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
449	    @Override
450	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
451	        Owner owner = this.clinicService.findOwnerById(ownerId);
452	        if (owner != null) {
453	            Pet pet = owner.getPet(petId);
454	            if (pet != null) {
455	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
456	            }
457	        }
458	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
459	    }
460	
461	    /**
462	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
463	     * The address is normalized in place (so a required-field check that follows rejects an
464	     * address blank after normalization), the required fields are checked, the telephone and
465	     * email are normalized in place, and the resulting owner is rejected when its derived
466	     * identity key already belongs to another owner. Each rule
467	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
468	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
469	     * to be mapped and saved.
470	     *
471	     * @param ownerFieldsDto the submitted owner fields, normalized in place
472	     */
473	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
474	        applyAddress(ownerFieldsDto);
475	        validateRequiredFields(ownerFieldsDto);
476	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
477	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
478	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
479	        rejectDuplicateIdentity(ownerFieldsDto);
480	        rejectCityAtCapacity(ownerFieldsDto.getCity());
481	        rejectDailyLimitExceeded(registrationDate);
