484	    /**
485	     * Applies an owner's address to the submitted fields, normalizing it in place into the
486	     * canonical form stored and returned for the owner. This is the single intake step that owns
487	     * how a submitted address becomes an owner's stored address: it delegates every transform to
488	     * {@link #normalizeAddress(String)}, the single definition of address normalization, and writes
489	     * the results back onto {@code ownerFieldsDto}.
490	     *
491	     * <p>The structured fields are preferred when supplied: when a non-blank {@code addressLine1}
492	     * is present the two structured lines are normalized in place and the flat {@code address} is
493	     * (re)composed from them — the normalized {@code addressLine1}, with a single space and the
494	     * normalized {@code addressLine2} appended only when an {@code addressLine2} was supplied — so
495	     * every rule that later reads {@code address} sees the structured value. When no structured
496	     * {@code addressLine1} is supplied the flat {@code address} is normalized in place, preserving
497	     * backward compatibility.
498	     *
499	     * <p>It runs ahead of {@link #validateRequiredFields(OwnerFieldsDto)} so an address that is
500	     * blank after normalization in either form is rejected by the required-field check that
501	     * follows. Isolating the step here keeps {@link #prepareNewOwner(OwnerFieldsDto, LocalDate)} a
502	     * list of named intake steps and gives address handling one place to grow.
503	     *
504	     * @param ownerFieldsDto the submitted owner fields, whose address is normalized in place
505	     */
506	    private void applyAddress(OwnerFieldsDto ownerFieldsDto) {
507	        String line1 = ownerFieldsDto.getAddressLine1();
508	        if (line1 != null && !line1.isBlank()) {
509	            String normalizedLine1 = normalizeAddress(line1);
510	            ownerFieldsDto.setAddressLine1(normalizedLine1);
511	            String line2 = ownerFieldsDto.getAddressLine2();
512	            if (line2 != null && !line2.isBlank()) {
513	                String normalizedLine2 = normalizeAddress(line2);
514	                ownerFieldsDto.setAddressLine2(normalizedLine2);
515	                ownerFieldsDto.setAddress(normalizedLine1 + " " + normalizedLine2);
516	            } else {
517	                ownerFieldsDto.setAddressLine2(null);
518	                ownerFieldsDto.setAddress(normalizedLine1);
519	            }
520	        } else {
521	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
522	        }
523	    }
