525	    /**
526	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
527	     * falls on a business day. The date supplied on the request is used when present, otherwise the
528	     * server's current date is used. When that effective date lands on a Saturday, Sunday or listed
529	     * public holiday it is rolled forward to the next non-holiday business day; a non-holiday weekday
530	     * is left unchanged. This single adjusted date
531	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
532	     * membership number's year segment, the per-day create limit) is computed against.
533	     *
534	     * A supplied registration date later than the server's current date is rejected with an
535	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
536	     *
537	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
538	     * @return the effective registration date rolled forward to the next business day
539	     */
540	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
541	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
542	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
543	            throw new InvalidFieldsException(List.of("registrationDate"));
544	        }
545	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
546	        return toBusinessDay(effective);
547	    }
