694	    /**
695	     * Builds the unified {@code memberId} assigned to a newly created owner. The id is formatted as
696	     * {@code '<REGION><FY><HASH8><CHK>'}, concatenating (with no separators) the owner's region code
697	     * (see {@link Owner#getRegionCode()}, rendered {@code 'UNKNOWN'} when the owner has no known
698	     * region), the two-digit fiscal-year segment its business-day-adjusted {@code registrationDate}
699	     * falls in (see {@link Owner#fiscalYearSegment(LocalDate)}), its identity hash (see
700	     * {@link Owner#getIdentityHash()}, the first 8 upper-case hex characters of the SHA-256 digest
701	     * over the owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}) and
702	     * a single Luhn check digit (see {@link Owner#luhnCheckDigit(String)}) computed over the digits of
703	     * {@code <REGION><FY><HASH8>}. The composed base is then de-duplicated against existing owners
704	     * (see {@link #deduplicateMemberId(String)}). The base carries no sequence number, so two owners
705	     * sharing a region, fiscal year, telephone and last name resolve to the same base and are
706	     * separated only by de-duplication.
707	     *
708	     * @param owner the owner being created, whose fields the id is derived from
709	     * @return the formatted member id
710	     */
711	    private String memberIdFor(Owner owner) {
712	        String prefix = owner.getRegionCode()
713	            + Owner.fiscalYearSegment(owner.getRegistrationDate())
714	            + owner.getIdentityHash();
715	        return deduplicateMemberId(prefix + Owner.luhnCheckDigit(prefix));
716	    }
717	
718	    /**
719	     * Ensures the computed {@code memberId} is unique across existing owners. When the given base id
720	     * collides with an existing owner's {@code memberId}, {@code '-<n>'} is appended with the smallest
721	     * {@code n} of 2 or more that yields an id no existing owner already carries.
722	     *
723	     * @param baseCode the member id computed for the owner being created
724	     * @return the base id when it is already unique, otherwise the de-duplicated id
725	     */
726	    private String deduplicateMemberId(String baseCode) {
727	        Set<String> existing = this.clinicService.findAllOwners().stream()
728	            .map(Owner::getMemberId)
729	            .filter(Objects::nonNull)
730	            .collect(Collectors.toSet());
731	        if (!existing.contains(baseCode)) {
732	            return baseCode;
733	        }
734	        int n = 2;
735	        while (existing.contains(baseCode + "-" + n)) {
736	            n++;
737	        }
738	        return baseCode + "-" + n;
739	    }
