758	    /**
759	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
760	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it does not share
761	     * an existing owner's identity key. A member that declared its household via
762	     * {@code sharesHousehold} is a deliberate addition to a known household, not a suspected
763	     * duplicate, so it is never flagged. Otherwise it is a possible duplicate when an existing owner
764	     * shares the Soundex code of its {@code lastName} and its {@code postcode} while carrying a
765	     * different identity key (see {@link #findPossibleDuplicate(Owner)}). When such an owner is
766	     * found, {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to the
767	     * matching owner's id; otherwise {@code possibleDuplicate} is set {@code false} and no matching
768	     * id is recorded. An owner without a postcode can share no postcode and is never a possible
769	     * duplicate.
770	     *
771	     * @param owner the owner being created, already carrying its normalized telephone and postcode
772	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
773	     */
774	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
775	        owner.setPossibleDuplicate(false);
776	        owner.setPossibleDuplicateOf(null);
777	        if (sharesHousehold(ownerFieldsDto)) {
778	            return;
779	        }
780	        findPossibleDuplicate(owner).ifPresent(existing -> {
781	            owner.setPossibleDuplicate(true);
782	            owner.setPossibleDuplicateOf(existing.getId());
783	        });
784	    }
