786	    /**
787	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
788	     * duplicate: a non-deleted owner whose {@code lastName} shares the new owner's Soundex code (see
789	     * {@link Owner#soundex(String)}) and whose {@code postcode} matches, while carrying a different
790	     * identity key (see {@link Owner#identityKey(String, String, String)}). Requiring a differing
791	     * identity key keeps a hard duplicate — already rejected with 409 by
792	     * {@link #rejectDuplicateIdentity(OwnerFieldsDto)} — from also being flagged as a soft match, so
793	     * the two household members whose telephones differ (hence differing identity keys, but matching
794	     * Soundex and postcode) are exactly the soft matches surfaced here. This is the single definition
795	     * of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records
796	     * the outcome on the owner. An owner without a postcode can share no postcode and matches nothing,
797	     * so {@link java.util.Optional#empty()} is returned.
798	     *
799	     * @param owner the owner being created, already carrying its normalized telephone and postcode
800	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
801	     */
802	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
803	        if (owner.getPostcode() == null) {
804	            return java.util.Optional.empty();
805	        }
806	        String soundex = Owner.soundex(owner.getLastName());
807	        String identityKey = owner.getIdentityKey();
808	        return this.clinicService.findAllOwners().stream()
809	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
810	            .filter(existing -> !identityKey.equals(existing.getIdentityKey())
811	                && soundex.equals(Owner.soundex(existing.getLastName()))
812	                && owner.getPostcode().equals(existing.getPostcode()))
813	            .findFirst();
814	    }
