843	    /**
844	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
845	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
846	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
847	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
848	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
849	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
850	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
851	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
852	     *
853	     * @param telephone the submitted telephone value
854	     * @return the normalized E.164 telephone
855	     */
856	    private String normalizeTelephone(String telephone) {
857	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
858	        String e164;
859	        if (cleaned.startsWith("+")) {
860	            e164 = "+" + cleaned.substring(1);
861	        } else {
862	            String national = cleaned;
863	            if (national.startsWith("0")) {
864	                national = national.substring(1);
865	            }
866	            e164 = "+61" + national;
867	        }
868	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
869	            throw new InvalidFieldsException(List.of("telephone"));
870	        }
871	        validateNationalNumberLength(e164);
872	        return e164;
873	    }
874	
875	    /**
876	     * Validates the national-number length of an already syntactically valid E.164 telephone
877	     * against its country code. When the number carries a country code this application recognizes
878	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
879	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
880	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
881	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
882	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
883	     * that is not recognized carries no per-country length rule and is left to the general
884	     * 8-to-15-digit E.164 check.
885	     *
886	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
887	     */
888	    private void validateNationalNumberLength(String e164) {
889	        String countryCode = Owner.countryCodeOf(e164);
890	        if (countryCode == null) {
891	            return;
892	        }
893	        int nationalLength = e164.length() - 1 - countryCode.length();
894	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
895	            throw new InvalidFieldsException(List.of("telephone"));
896	        }
897	    }
