962	    /**
963	     * Extracts the lower-cased domain of an email — everything after its final {@code '@'}. This is
964	     * the single definition of an email's domain, shared wherever an owner's email is matched by its
965	     * domain (for example the disposable-domain blocklist applied in {@link #normalizeEmail(String)}),
966	     * so every such rule reads the domain identically rather than re-deriving it. A {@code null} email
967	     * (none was supplied) has no domain and yields {@code null}. Like {@link #canonicalEmail(String)}
968	     * no validation is performed, so this can be applied to a value read back off an existing owner as
969	     * readily as to one being normalized; a caller that needs a syntactically valid address validates
970	     * it first. The domain is lower-cased so it compares case-insensitively, matching how
971	     * {@link #DISPOSABLE_EMAIL_DOMAINS} is compared. For example {@code "jane@Example.COM"} yields
972	     * {@code "example.com"}.
973	     *
974	     * @param email the email whose domain to extract, or {@code null} when none was supplied
975	     * @return the lower-cased domain, or {@code null} when {@code email} is {@code null}
976	     */
977	    private String emailDomain(String email) {
978	        if (email == null) {
979	            return null;
980	        }
981	        return email.substring(email.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
982	    }
983	
984	    /**
985	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
986	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
987	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
988	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
989	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
990	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
991	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
992	     * 400 response naming the {@code postcode} field.
993	     *
994	     * @param postcode the submitted postcode, or {@code null} when omitted
995	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
996	     */
997	    private void validatePostcode(String postcode, String city) {
998	        if (postcode == null) {
999	            return;
1000	        }
1001	        if (!postcode.matches("^[0-9]{4}$")) {
1002	            throw new InvalidFieldsException(List.of("postcode"));
1003	        }
1004	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
1005	        if (range != null) {
1006	            int value = Integer.parseInt(postcode);
1007	            if (value < range[0] || value > range[1]) {
1008	                throw new InvalidFieldsException(List.of("postcode"));
1009	            }
1010	        }
1011	    }
1012	
1013	    /**
1014	     * Rejects a new owner that is an exact identity duplicate of an existing owner. An owner's
1015	     * identity is its single derived identity key (see
1016	     * {@link Owner#identityKey(String, String, String)}) — the SHA-256 hex digest over its
1017	     * normalized {@code telephone}, canonical {@code email} and the Soundex code of its
1018	     * {@code lastName} — so a new owner is a hard duplicate only when some existing, non-deleted
1019	     * owner carries the same identity key. The email-domain blocklist has already been applied when
1020	     * the email was normalized ahead of this check, so a disposable-domain email is rejected before
1021	     * duplicate detection runs. Two owners that merely belong to the same household (the same last
1022	     * name and postcode) but carry different telephones now have distinct identity keys and are not
1023	     * rejected here; such a near-match is instead recorded as a soft {@code possibleDuplicate} (see
1024	     * {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)}). When an existing owner shares the new
1025	     * owner's identity key a {@link DuplicateIdentityException} is thrown, which the exception advice
1026	     * renders as a 409 Conflict response. Setting {@code sharesHousehold} declares the owner a
1027	     * deliberate household member and bypasses this block.
1028	     *
1029	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
1030	     */
1031	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
1032	        if (sharesHousehold(ownerFieldsDto)) {
1033	            return;
1034	        }
1035	        String identityKey = Owner.identityKey(ownerFieldsDto.getTelephone(),
1036	            ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
1037	        boolean taken = this.clinicService.findAllOwners().stream()
1038	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1039	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
1040	        if (taken) {
1041	            throw new DuplicateIdentityException(identityKey);
1042	        }
1043	    }
1044	
1045	    /**
1046	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
1047	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
1048	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
1049	     * resolves to the same stable value automatically, without any explicit linking. An owner without
1050	     * a postcode belongs to no shared household and is left without a household identifier.
1051	     *
1052	     * @param owner the newly created owner, mutated in place with its household identifier
1053	     */
1054	    private void assignHousehold(Owner owner) {
1055	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
1056	    }
1057	
1058	    /**
1059	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
1060	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
1061	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
1062	     * every rule that treats a declared household member differently from an independent owner.
1063	     *
1064	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
1065	     * @return {@code true} when the request opted into sharing a household
1066	     */
1067	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
1068	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
1069	    }
1070	
1071	    /**
1072	     * Derives the stable {@code householdId} shared by every owner in the household identified by
1073	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
1074	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
1075	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
1076	     * postcode — regardless of creation order or address — resolve to the same identifier
1077	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
1078	     * returned.
1079	     *
1080	     * @param lastName the household's last name
1081	     * @param postcode the household's postcode, or {@code null} when the owner has none
1082	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
1083	     */
1084	    private String householdIdFor(String lastName, String postcode) {
1085	        if (postcode == null) {
1086	            return null;
1087	        }
1088	        return shaHex(householdKey(lastName, postcode), 12);
1089	    }
1090	
1091	    /**
1092	     * Builds the canonical household key that identifies the household a {@code lastName} and
1093	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
1094	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
1095	     * owner fields make up a household and how they are normalized;
1096	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
1097	     * owners in the same household resolve to the same key and therefore the same identifier.
1098	     *
1099	     * @param lastName the household's last name
1100	     * @param postcode the household's postcode
1101	     * @return the normalized household key
1102	     */
1103	    private String householdKey(String lastName, String postcode) {
1104	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
1105	    }
1106	
1107	    /**
1108	     * Returns the leading {@code hexChars} upper-case hex characters of the SHA-256 digest of a
1109	     * string, the form used by the derived owner codes (for example the customer code and household
1110	     * identifier). Delegates to {@link Owner#shaHexPrefix(String, int)}, the single definition of the
1111	     * truncated upper-case hex derivation, so {@code hexChars} characters cover the leading
1112	     * {@code ceil(hexChars / 2)} bytes of the digest.
1113	     *
1114	     * @param input the string to hash
1115	     * @param hexChars the number of leading upper-case hex characters to return
1116	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
1117	     */
1118	    private String shaHex(String input, int hexChars) {
1119	        return Owner.shaHexPrefix(input, hexChars);
1120	    }
1121	
1122	    /**
1123	     * Returns the owners that belong to the household identified by the given {@code householdId},
1124	     * i.e. every owner carrying that exact identifier. Soft-deleted owners are included, so a caller
1125	     * that must ignore deleted owners (as {@link #rejectDuplicateIdentity(OwnerFieldsDto)} does)
1126	     * filters them out itself. The owners are taken from the current set, so after a create the
1127	     * result includes the newly persisted owner. An owner without a household (a {@code null}
1128	     * identifier) belongs to no shared household, so an empty list is returned. This is the single
1129	     * definition of a household's members, shared by every rule that reasons about the owners
1130	     * sharing a household (the household-duplicate block and the household member count).
1131	     *
1132	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1133	     * @return the owners in the household, or an empty list when {@code householdId} is {@code null}
1134	     */
1135	    private List<Owner> householdMembers(String householdId) {
1136	        if (householdId == null) {
1137	            return List.of();
1138	        }
1139	        return this.clinicService.findAllOwners().stream()
1140	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
1141	            .collect(Collectors.toList());
1142	    }
1143	
1144	    /**
1145	     * Counts the owners that belong to the household identified by the given {@code householdId} (see
1146	     * {@link #householdMembers(String)}), i.e. every owner carrying that exact identifier. The count
1147	     * is taken against the current set of owners, so after a create it reflects the household's size
1148	     * including the newly persisted owner. An owner without a household (a {@code null} identifier)
1149	     * belongs to no shared household and yields {@code 0}.
1150	     *
1151	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
1152	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
1153	     */
1154	    private int countHouseholdMembers(String householdId) {
1155	        return householdMembers(householdId).size();
1156	    }
1157	
1158	    /**
1159	     * Stamps an owner with its household member count, the number of owners sharing its household
1160	     * (see {@link #countHouseholdMembers(String)}), so every value the owner derives from its
1161	     * household size (its membership factor and level) reads a populated count rather than the
1162	     * unstamped default. This is the single definition of hydrating an owner with its household
1163	     * member count, shared by the create and read paths that render an owner's derived values.
1164	     *
1165	     * @param owner the owner to stamp, mutated in place with its household member count
1166	     */
1167	    private void applyHouseholdMemberCount(Owner owner) {
1168	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1169	    }
1170	
1171	    /**
1172	     * Resolves the household level ceiling a newly created owner is subject to: one above the
1173	     * current maximum {@code membershipLevel} among the existing, non-deleted owners already
1174	     * sharing its household (see {@link #householdMembers(String)}). Each existing member is
1175	     * stamped with its household member count first so its {@link Owner#getMembershipLevel()}
1176	     * reads a populated count, mirroring how the create and read paths render a member's derived
1177	     * level. The ceiling is taken before the new owner is persisted, so it reflects only the
1178	     * members already in the household. When the owner joins an empty household — no household
1179	     * identifier, or no existing member — no ceiling applies and {@code null} is returned, letting
1180	     * the owner earn its uncapped level (see {@link Owner#cappedMembershipLevel(int, Integer)}).
1181	     *
1182	     * @param householdId the shared household identifier of the owner being created, or {@code null}
1183	     * @return one above the household's current maximum membership level, or {@code null} when no ceiling applies
1184	     */
1185	    private Integer householdMembershipLevelCap(String householdId) {
1186	        java.util.OptionalInt max = householdMembers(householdId).stream()
1187	            .filter(existing -> !Owner.isDeleted(existing.getDeleted()))
1188	            .peek(this::applyHouseholdMemberCount)
1189	            .mapToInt(Owner::getMembershipLevel)
1190	            .max();
1191	        return max.isPresent() ? max.getAsInt() + 1 : null;
1192	    }
1193	
1194	    /**
1195	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
1196	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
1197	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
1198	     *
1199	     * @param value the value to collapse, or {@code null}
1200	     * @return the whitespace-collapsed value, never {@code null}
1201	     */
1202	    private String collapseWhitespace(String value) {
1203	        if (value == null) {
1204	            return "";
1205	        }
1206	        return value.trim().replaceAll("\\s+", " ");
1207	    }
1208	
1209	    /**
1210	     * Common street-type abbreviations expanded during address normalization, keyed by their
1211	     * upper-cased token.
1212	     */
1213	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
1214	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
1215	
1216	    /**
1217	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
1218	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
1219	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
1220	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
1221	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
1222	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
1223	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
1224	     * everywhere an address is stored or compared.
1225	     *
1226	     * @param address the submitted address value, or {@code null}
1227	     * @return the normalized address, never {@code null}
1228	     */
1229	    private String normalizeAddress(String address) {
1230	        if (address == null) {
1231	            return "";
1232	        }
1233	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
1234	        if (collapsed.isEmpty()) {
1235	            return "";
1236	        }
1237	        String[] tokens = collapsed.split(" ");
1238	        StringBuilder sb = new StringBuilder(collapsed.length());
1239	        for (int i = 0; i < tokens.length; i++) {
1240	            if (i > 0) {
1241	                sb.append(' ');
1242	            }
1243	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
1244	        }
1245	        return sb.toString();
1246	    }
1247	}
