1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Derives the owner's {@code selfLink}: the canonical URI path of the owner, formed as
33	     * {@code '/api/owners/'} followed by its id. Returns {@code null} when the owner has no id
34	     * yet, leaving {@code selfLink} absent from the response.
35	     */
36	    default String selfLink(Owner owner) {
37	        if (owner == null || owner.getId() == null) {
38	            return null;
39	        }
40	        return "/api/owners/" + owner.getId();
41	    }
42	
43	    /**
44	     * Derives the owner's age band as the DTO enum, rendering the owner's derived age band (see
45	     * {@link Owner#getAgeBand()}). Returns {@code null} when the owner has no derivable age band
46	     * (no birthDate or no registrationDate), leaving {@code ageBand} absent from the response.
47	     */
48	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
49	        if (owner == null || owner.getAgeBand() == null) {
50	            return null;
51	        }
52	        return OwnerDto.AgeBandEnum.valueOf(owner.getAgeBand());
53	    }
54	
55	    /**
56	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email address
57	     * is present (non-null and non-blank), otherwise {@code 'PHONE'}.
58	     */
59	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        return Owner.hasEmail(owner.getEmail())
64	            ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
65	    }
66	
67	    /**
68	     * Derives the owner's segment as {@code '<TIER>_<AREA>'}. TIER is {@code 'PREMIUM'} when the
69	     * owner's derived {@code membershipLevel} (see {@link Owner#getMembershipLevel()}) is 3 or more,
70	     * otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's locality is a known
71	     * region ({@code NSW}, {@code VIC} or {@code QLD}; see {@link #localityRegion(Owner)}), otherwise
72	     * {@code 'REGIONAL'}.
73	     */
74	    default OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
75	        if (owner == null) {
76	            return null;
77	        }
78	        Integer level = owner.getMembershipLevel();
79	        String tier = (level != null && level >= 3) ? "PREMIUM" : "STANDARD";
80	        String region = localityRegion(owner);
81	        String area = (region != null && REGION_TIMEZONES.containsKey(region)) ? "METRO" : "REGIONAL";
82	        return OwnerDto.OwnerSegmentEnum.valueOf(tier + "_" + area);
83	    }
84	
85	    /**
86	     * Derives the owner's locality from the region its identity carries (see
87	     * {@link #localityRegion(Owner)}). Returns that region string, or {@code 'UNKNOWN'} when the
88	     * owner has no known region.
89	     */
90	    default String locality(Owner owner) {
91	        if (owner == null) {
92	            return null;
93	        }
94	        String region = localityRegion(owner);
95	        return region != null ? region : "UNKNOWN";
96	    }
97	
98	    /**
99	     * Resolves the region an owner's {@link #locality(Owner)} is derived from. This is the
100	     * {@code REGION} segment the owner's unified {@code memberId} leads with, whose
101	     * {@code '<REGION><FY><HASH8><CHK>'} identity encodes the region as its prefix. The sentinel
102	     * {@code 'UNKNOWN'} region (used when the owner has no known region) and a missing member id both
103	     * resolve to {@code null}, since only the known regions ({@code NSW}, {@code VIC}, {@code QLD})
104	     * the member id can begin with are returned. Keeping the region source in its own method leaves
105	     * {@link #locality(Owner)} owning only the {@code null -> 'UNKNOWN'} rendering, so where the
106	     * region itself comes from can change without disturbing that rendering.
107	     *
108	     * @param owner the owner whose locality region is resolved, never {@code null}
109	     * @return the region string, or {@code null} when the owner has no known region
110	     */
